      (autoPronounce ? 'rgba(56,189,248,0.3)' : 'rgba(255,255,255,0.06)') + ';color:' +
      (autoPronounce ? '#ffffff' : '#94a3b8') + ';font-size:12px;font-weight:600;cursor:pointer;';
