// ============================================================================
// MISSION #335: Weak Cards Vault & Pre-Exam Cramming Mode (v4.6.5)
// ============================================================================
function dfGetWeakCardsCrammingQueue(cardsList, options) {
  const list = Array.isArray(cardsList) ? cardsList : [];
  const opts = options || {};
  const maxCards = typeof opts.maxCards === "number" && opts.maxCards > 0 ? Math.min(100, Math.floor(opts.maxCards)) : 20;
  const deckFilter = opts.deckFilter && typeof opts.deckFilter === "string" ? opts.deckFilter.trim().toLowerCase() : null;

  const scoredCards = [];
  let totalWeak = 0;
  let highRisk = 0;

  for (const c of list) {
    if (!c || !c.term) continue;
    if (deckFilter && (c.deck || "General").trim().toLowerCase() !== deckFilter) continue;

    const lapses = typeof c.lapses === "number" ? c.lapses : (typeof c.incorrectCount === "number" ? c.incorrectCount : 0);
    const correct = typeof c.correctReviews === "number" ? c.correctReviews : 0;
    const totalRev = lapses + correct;
    const accuracy = totalRev > 0 ? (correct / totalRev) : 0.5;
    const box = typeof c.box === "number" && c.box >= 1 && c.box <= 5 ? c.box : 1;

    const boxPenalty = (6 - box) * 12;
    const lapsePenalty = lapses * 18;
    const accuracyPenalty = Math.round((1.0 - accuracy) * 50);
    const weaknessScore = boxPenalty + lapsePenalty + accuracyPenalty;

    const isWeak = (box <= 2) || (lapses >= 2) || (totalRev >= 2 && accuracy < 0.6);
    if (isWeak) {
      totalWeak++;
      if (box === 1 && (lapses >= 3 || accuracy < 0.4)) {
        highRisk++;
      }
      scoredCards.push({
        id: c.id || "card_" + Math.random(),
        term: c.term,
        definition: c.definition || "",
        deck: c.deck || "General",
        box: box,
        lapses: lapses,
        accuracyPercent: Math.round(accuracy * 100),
        weaknessScore: weaknessScore
      });
    }
  }

  scoredCards.sort((a, b) => b.weaknessScore - a.weaknessScore);
  const queue = scoredCards.slice(0, maxCards);

  let totalAcc = 0;
  for (const q of queue) {
    totalAcc += q.accuracyPercent;
  }
  const avgAccuracy = queue.length > 0 ? Math.round(totalAcc / queue.length) : 0;
  const recommendedMinutes = Math.max(3, Math.ceil(queue.length * 0.75));

  return {
    versionCode: 155,
    versionName: "4.6.5",
    crammingMode: true,
    queueLength: queue.length,
    totalWeakCardsInVault: totalWeak,
    highRiskCount: highRisk,
    averageWeakAccuracyPercent: avgAccuracy,
    recommendedCramMinutes: recommendedMinutes,
    cramCards: queue,
    westernDigits: true,
    timestamp: Date.now()
  };
}

if (typeof window !== "undefined") {
  window.dfGetWeakCardsCrammingQueue = dfGetWeakCardsCrammingQueue;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfGetWeakCardsCrammingQueue = dfGetWeakCardsCrammingQueue;
}

// ============================================================================
// MISSION #336: Long-Term Memory Retention Index Calculator (v4.6.6)
// ============================================================================
function dfCalculateLongTermRetentionIndex(cardsList, options) {
  const list = Array.isArray(cardsList) ? cardsList : [];
  const opts = options || {};
  const now = typeof opts.currentTime === "number" ? opts.currentTime : Date.now();

  if (list.length === 0) {
    return {
      versionCode: 156,
      versionName: "4.6.6",
      retentionIndexPercent: 100,
      retentionGrade: "A+ (EXEMPLARY)",
      totalCardsEvaluated: 0,
      masteredCardsCount: 0,
      atRiskCardsCount: 0,
      projected7DayRetentionPercent: 100,
      formattedGradeSummary: "100% • A+ (EXEMPLARY)",
      westernDigits: true,
      timestamp: now
    };
  }

  let totalR = 0;
  let totalR7 = 0;
  let mastered = 0;
  let atRisk = 0;

  for (const c of list) {
    if (!c) continue;
    const intervalDays = typeof c.intervalDays === "number" && c.intervalDays > 0 ? c.intervalDays : (typeof c.box === "number" ? [1, 1, 2, 5, 9, 14][c.box] || 1 : 1);
    const streak = typeof c.consecutiveCorrect === "number" && c.consecutiveCorrect >= 0 ? c.consecutiveCorrect : 1;
    const lastRev = typeof c.lastReviewed === "number" ? c.lastReviewed : (now - 86400000);

    const stability = Math.max(1, intervalDays * Math.min(2.5, 1 + streak * 0.15));
    const elapsedDays = Math.max(0, (now - lastRev) / (24 * 60 * 60 * 1000));

    const r = Math.exp(-elapsedDays / stability);
    const r7 = Math.exp(-(elapsedDays + 7) / stability);

    totalR += r;
    totalR7 += r7;

    if (r >= 0.88 && stability >= 10) {
      mastered++;
    } else if (r < 0.70) {
      atRisk++;
    }
  }

  const avgRetention = Math.min(100, Math.max(0, Math.round((totalR / list.length) * 100)));
  const avgRetention7 = Math.min(100, Math.max(0, Math.round((totalR7 / list.length) * 100)));

  let grade = "A (EXCELLENT)";
  if (avgRetention >= 93) grade = "A+ (EXEMPLARY)";
  else if (avgRetention >= 80) grade = "A (EXCELLENT)";
  else if (avgRetention >= 70) grade = "B (SOLID)";
  else grade = "C (NEEDS_REVIEW)";

  return {
    versionCode: 156,
    versionName: "4.6.6",
    retentionIndexPercent: avgRetention,
    retentionGrade: grade,
    totalCardsEvaluated: list.length,
    masteredCardsCount: mastered,
    atRiskCardsCount: atRisk,
    projected7DayRetentionPercent: avgRetention7,
    formattedGradeSummary: avgRetention + "% • " + grade,
    westernDigits: true,
    timestamp: now
  };
}

if (typeof window !== "undefined") {
  window.dfCalculateLongTermRetentionIndex = dfCalculateLongTermRetentionIndex;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfCalculateLongTermRetentionIndex = dfCalculateLongTermRetentionIndex;
}

// ============================================================================
// MISSION #337: Multi-Tagging & Subject Color Matrix (v4.6.7)
// ============================================================================
function dfManageCardTagsAndColorMatrix(card, action, tagPayload) {
  const c = card || {};
  const act = (action || "GET").toUpperCase();
  const payload = tagPayload || {};

  const colorMatrix = {
    "BLUE": { hex: "#38BDF8", subject: "STEM / Computer Science" },
    "EMERALD": { hex: "#34D399", subject: "Biology / Medicine" },
    "AMBER": { hex: "#FBBF24", subject: "Law / Economics" },
    "ROSE": { hex: "#FB7185", subject: "History / Humanities" },
    "VIOLET": { hex: "#A78BFA", subject: "Languages / Vocabulary" },
    "SLATE": { hex: "#94A3B8", subject: "General / Miscellaneous" }
  };

  let currentTags = Array.isArray(c.tags) ? [...c.tags] : [];
  let currentColor = c.colorCode || colorMatrix.SLATE.hex;
  let currentSubject = c.subjectName || "SLATE";

  const sanitizeTag = (t) => {
    let s = String(t || "").trim().toLowerCase().replace(/\s+/g, "_");
    if (!s.startsWith("#")) s = "#" + s;
    return s;
  };

  if (act === "ADD_TAG" && payload.tag) {
    const clean = sanitizeTag(payload.tag);
    if (!currentTags.includes(clean)) currentTags.push(clean);
  } else if (act === "REMOVE_TAG" && payload.tag) {
    const clean = sanitizeTag(payload.tag);
    currentTags = currentTags.filter(t => t !== clean);
  } else if (act === "SET_TAGS_BULK" && Array.isArray(payload.tags)) {
    currentTags = payload.tags.map(sanitizeTag).filter((v, i, a) => a.indexOf(v) === i);
  } else if (act === "SET_COLOR" && payload.colorName) {
    const name = String(payload.colorName).toUpperCase().trim();
    if (colorMatrix[name]) {
      currentColor = colorMatrix[name].hex;
      currentSubject = name;
    }
  }

  c.tags = currentTags;
  c.colorCode = currentColor;
  c.subjectName = currentSubject;

  return {
    versionCode: 157,
    versionName: "4.6.7",
    cardId: c.id || "card_tag",
    tags: currentTags,
    colorCode: currentColor,
    subjectName: currentSubject,
    totalTagsOnCard: currentTags.length,
    westernDigits: true,
    timestamp: Date.now()
  };
}

function dfFilterCardsByTagMatrix(cardsList, filterCriteria) {
  const list = Array.isArray(cardsList) ? cardsList : [];
  const criteria = filterCriteria || {};
  const targetTag = criteria.tag ? String(criteria.tag).toLowerCase().trim() : null;
  const targetColor = criteria.subjectName ? String(criteria.subjectName).toUpperCase().trim() : null;

  const tagDistribution = {};
  const filtered = [];

  for (const c of list) {
    if (!c) continue;
    const tags = Array.isArray(c.tags) ? c.tags : [];
    const subject = c.subjectName || "SLATE";

    for (const t of tags) {
      tagDistribution[t] = (tagDistribution[t] || 0) + 1;
    }

    let match = true;
    if (targetTag && !tags.some(t => t.toLowerCase() === targetTag || t.toLowerCase() === "#" + targetTag)) {
      match = false;
    }
    if (targetColor && subject !== targetColor) {
      match = false;
    }

    if (match) filtered.push(c);
  }

  return {
    versionCode: 157,
    versionName: "4.6.7",
    matchingCardsCount: filtered.length,
    totalCardsEvaluated: list.length,
    filteredCards: filtered,
    tagDistribution: tagDistribution,
    westernDigits: true,
    timestamp: Date.now()
  };
}

if (typeof window !== "undefined") {
  window.dfManageCardTagsAndColorMatrix = dfManageCardTagsAndColorMatrix;
  window.dfFilterCardsByTagMatrix = dfFilterCardsByTagMatrix;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfManageCardTagsAndColorMatrix = dfManageCardTagsAndColorMatrix;
  globalThis.dfFilterCardsByTagMatrix = dfFilterCardsByTagMatrix;
}

// ============================================================================
// MISSION #338: Android Offline Native TTS Engine Pronunciation Hook (v4.6.8)
// ============================================================================
function dfSynthesizeCardPronunciation(termText, langCode, options) {
  const text = String(termText || "").trim();
  const rawLang = String(langCode || "en-US").trim();
  const opts = options || {};

  const lowerLang = rawLang.toLowerCase();
  if (lowerLang.startsWith("he") || lowerLang.startsWith("iw") || /[\u0590-\u05FF]/.test(text)) {
    return {
      versionCode: 158,
      versionName: "4.6.8",
      error: "FORBIDDEN_LOCALE_OR_SCRIPT",
      isDispatched: false,
      timestamp: Date.now()
    };
  }

  if (!text) {
    return {
      versionCode: 158,
      versionName: "4.6.8",
      error: "EMPTY_TEXT",
      isDispatched: false,
      timestamp: Date.now()
    };
  }

  const rate = typeof opts.speechRate === "number" && opts.speechRate >= 0.5 && opts.speechRate <= 2.0
    ? Math.round(opts.speechRate * 100) / 100
    : 0.85;
  const pitch = typeof opts.speechPitch === "number" && opts.speechPitch >= 0.5 && opts.speechPitch <= 1.5
    ? Math.round(opts.speechPitch * 100) / 100
    : 1.0;

  let engineUsed = "SIMULATED_VM";

  if (typeof window !== "undefined") {
    if (window.AndroidBridge && typeof window.AndroidBridge.speakText === "function") {
      try {
        window.AndroidBridge.speakText(text, rawLang, rate, pitch);
        engineUsed = "ANDROID_NATIVE_TTS_BRIDGE";
      } catch (e) {
        engineUsed = "BRIDGE_ERROR_FALLBACK";
      }
    } else if (window.speechSynthesis && typeof window.SpeechSynthesisUtterance !== "undefined") {
      try {
        window.speechSynthesis.cancel();
        const utterance = new window.SpeechSynthesisUtterance(text);
        utterance.lang = rawLang;
        utterance.rate = rate;
        utterance.pitch = pitch;
        window.speechSynthesis.speak(utterance);
        engineUsed = "WEB_SPEECH_API";
      } catch (e) {
        engineUsed = "WEB_SPEECH_ERROR";
      }
    }
  }

  return {
    versionCode: 158,
    versionName: "4.6.8",
    term: text,
    locale: rawLang,
    rate: rate,
    pitch: pitch,
    engine: engineUsed,
    isDispatched: true,
    westernDigits: true,
    timestamp: Date.now()
  };
}

if (typeof window !== "undefined") {
  window.dfSynthesizeCardPronunciation = dfSynthesizeCardPronunciation;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfSynthesizeCardPronunciation = dfSynthesizeCardPronunciation;
}

