// ============================================================================
// MISSION #346: Local Storage & Vault Auto-Pruning Compression Engine (v4.7.6)
// ============================================================================
function dfCompressAndPruneVaultStorage(options, storageAdapter) {
  const opts = options || {};
  const storage = storageAdapter || (typeof localStorage !== "undefined" ? localStorage : null);
  const now = typeof opts.currentTime === "number" ? opts.currentTime : Date.now();
  const retentionDays = typeof opts.retentionDays === "number" && opts.retentionDays > 0 ? opts.retentionDays : 90;
  const cutoffTime = now - (retentionDays * 24 * 60 * 60 * 1000);

  if (!storage) {
    return {
      versionCode: 166,
      versionName: "4.7.6",
      storageStatus: "SKIPPED_NO_STORAGE",
      bytesFreed: 0,
      westernDigits: true,
      timestamp: now
    };
  }

  let bytesBefore = 0;
  const allKeys = [];
  if (typeof storage.length === "number") {
    for (let i = 0; i < storage.length; i++) {
      const k = storage.key(i);
      if (k) allKeys.push(k);
    }
  } else if (storage._data) {
    allKeys.push(...Object.keys(storage._data));
  }

  for (const k of allKeys) {
    const v = storage.getItem(k) || "";
    bytesBefore += (k.length + v.length) * 2;
  }

  const rawHistory = storage.getItem("df_v21_history");
  let historyList = [];
  try {
    historyList = JSON.parse(rawHistory) || [];
  } catch (e) {
    historyList = [];
  }

  const recentSessions = [];
  const monthlyBuckets = {};
  let prunedCount = 0;

  for (const s of historyList) {
    if (!s) continue;
    const ts = typeof s.timestamp === "number" ? s.timestamp : now;
    if (ts >= cutoffTime) {
      recentSessions.push(s);
    } else {
      prunedCount++;
      const d = new Date(ts);
      const mKey = d.getFullYear() + "-" + (d.getMonth() + 1 < 10 ? "0" + (d.getMonth() + 1) : (d.getMonth() + 1));
      if (!monthlyBuckets[mKey]) {
        monthlyBuckets[mKey] = { totalMinutes: 0, sessionCount: 0, totalRating: 0 };
      }
      monthlyBuckets[mKey].totalMinutes += (typeof s.durationMinutes === "number" ? s.durationMinutes : 25);
      monthlyBuckets[mKey].sessionCount++;
      monthlyBuckets[mKey].totalRating += (typeof s.rating === "number" ? s.rating : 4);
    }
  }

  if (!opts.dryRun && prunedCount > 0) {
    storage.setItem("df_v21_history", JSON.stringify(recentSessions));

    const rawArchive = storage.getItem("df_v21_history_monthly_archive");
    let existingArchive = {};
    try { existingArchive = JSON.parse(rawArchive) || {}; } catch (e) {}

    for (const [m, b] of Object.entries(monthlyBuckets)) {
      if (!existingArchive[m]) existingArchive[m] = { totalMinutes: 0, sessionCount: 0, avgRating: 4.0 };
      existingArchive[m].totalMinutes += b.totalMinutes;
      existingArchive[m].sessionCount += b.sessionCount;
      existingArchive[m].avgRating = Math.round((b.totalRating / b.sessionCount) * 10) / 10;
    }
    storage.setItem("df_v21_history_monthly_archive", JSON.stringify(existingArchive));
  }

  let orphanedRemoved = 0;
  const backupCutoff = now - (7 * 24 * 60 * 60 * 1000);
  for (const k of allKeys) {
    if (k.includes("_corrupt_bak_")) {
      const parts = k.split("_corrupt_bak_");
      const bakTime = parseInt(parts[1], 10);
      if (bakTime && bakTime < backupCutoff) {
        if (!opts.dryRun) storage.removeItem(k);
        orphanedRemoved++;
      }
    }
  }

  let bytesAfter = 0;
  for (const k of allKeys) {
    const v = storage.getItem(k) || "";
    bytesAfter += (k.length + v.length) * 2;
  }

  const bytesFreed = Math.max(0, bytesBefore - bytesAfter);
  const ratio = bytesBefore > 0 ? Math.round((bytesFreed / bytesBefore) * 100) : 0;

  return {
    versionCode: 166,
    versionName: "4.7.6",
    storageStatus: "OPTIMIZED",
    bytesUsedBefore: bytesBefore,
    bytesUsedAfter: bytesAfter,
    bytesFreed: bytesFreed,
    compressionRatioPercent: ratio,
    granularSessionsRetained: recentSessions.length,
    prunedSessionsArchived: prunedCount,
    orphanedKeysRemovedCount: orphanedRemoved,
    westernDigits: true,
    timestamp: now
  };
}

if (typeof window !== "undefined") {
  window.dfCompressAndPruneVaultStorage = dfCompressAndPruneVaultStorage;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfCompressAndPruneVaultStorage = dfCompressAndPruneVaultStorage;
}

// ============================================================================
// MISSION #347: Dual Multi-Track Nature Soundscape Mixer (v4.7.7)
// ============================================================================
function dfMixNatureSoundscapes(primaryTrack, secondaryTrack, masterOptions) {
  const p = primaryTrack || {};
  const s = secondaryTrack || {};
  const opts = masterOptions || {};

  const allowedSounds = ["RAIN", "STREAM", "FIRE", "WIND", "WHITE_NOISE", "OFF"];

  const sanitizeSound = (snd, defaultSnd) => {
    const u = String(snd || defaultSnd).toUpperCase().trim();
    return allowedSounds.includes(u) ? u : defaultSnd;
  };

  const sanitizeVol = (vol, defaultVol) => {
    const v = typeof vol === "number" ? vol : defaultVol;
    return Math.max(0.0, Math.min(1.0, Math.round(v * 100) / 100));
  };

  const primarySound = sanitizeSound(p.sound, "RAIN");
  const primaryVol = sanitizeVol(p.volume, 0.70);

  const secondarySound = sanitizeSound(s.sound, "OFF");
  const secondaryVol = sanitizeVol(s.volume, 0.30);

  const masterVol = sanitizeVol(opts.masterVolume, 1.0);
  const isMuted = Boolean(opts.isMuted);

  const effVolP = isMuted ? 0.0 : Math.round((primaryVol * masterVol) * 100) / 100;
  const effVolS = (isMuted || secondarySound === "OFF") ? 0.0 : Math.round((secondaryVol * masterVol) * 100) / 100;

  const isDual = primarySound !== "OFF" && secondarySound !== "OFF" && !isMuted;
  const activeSources = (primarySound !== "OFF" ? 1 : 0) + (secondarySound !== "OFF" && !isMuted ? 1 : 0);

  const soundProfiles = {
    "RAIN": { filterType: "lowpass", freqHz: 850, noise: "pink" },
    "STREAM": { filterType: "bandpass", freqHz: 1200, noise: "brown" },
    "FIRE": { filterType: "lowpass", freqHz: 600, popGenerator: "random_impulse" },
    "WIND": { filterType: "bandpass", freqHz: 400, lfoModulationHz: 0.2 },
    "WHITE_NOISE": { filterType: "allpass", freqHz: 1000, noise: "white" }
  };

  return {
    versionCode: 167,
    versionName: "4.7.7",
    isDualTrackActive: isDual,
    primaryTrack: {
      sound: primarySound,
      volume: primaryVol,
      effectiveVolume: effVolP,
      profile: soundProfiles[primarySound] || null
    },
    secondaryTrack: {
      sound: secondarySound,
      volume: secondaryVol,
      effectiveVolume: effVolS,
      profile: soundProfiles[secondarySound] || null
    },
    masterVolume: masterVol,
    isMuted: isMuted,
    totalActiveAudioSources: activeSources,
    smoothFadeMs: typeof opts.smoothFadeMs === "number" ? opts.smoothFadeMs : 1500,
    zeroMusicPolicy: true,
    westernDigits: true,
    timestamp: Date.now()
  };
}

if (typeof window !== "undefined") {
  window.dfMixNatureSoundscapes = dfMixNatureSoundscapes;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfMixNatureSoundscapes = dfMixNatureSoundscapes;
}

// ============================================================================
// MISSION #348: Motion-Sensing Audio Sleep Auto-Fade Timer (v4.7.8)
// ============================================================================
function dfGetMotionSleepFadeMetrics(motionState, options) {
  const s = motionState || {};
  const opts = options || {};

  const isEnabled = opts.enabled !== false;
  const now = typeof opts.currentTime === "number" ? opts.currentTime : Date.now();
  const lastMove = typeof s.lastMovementTime === "number" ? s.lastMovementTime : now;
  const isMoving = Boolean(s.isCurrentlyMoving);

  const stillnessMin = typeof opts.stillnessThresholdMinutes === "number" && opts.stillnessThresholdMinutes > 0 ? opts.stillnessThresholdMinutes : 20;
  const fadeMin = typeof opts.fadeDurationMinutes === "number" && opts.fadeDurationMinutes > 0 ? opts.fadeDurationMinutes : 5;

  const stillnessMs = stillnessMin * 60 * 1000;
  const fadeMs = fadeMin * 60 * 1000;

  if (!isEnabled) {
    return {
      versionCode: 168,
      versionName: "4.7.8",
      sleepTimerActive: false,
      state: "DISABLED",
      volumeMultiplier: 1.0,
      isAudioSuspended: false,
      westernDigits: true,
      timestamp: now
    };
  }

  if (isMoving && s.lastState && s.lastState !== "STILLNESS_COUNTDOWN") {
    return {
      versionCode: 168,
      versionName: "4.7.8",
      sleepTimerActive: true,
      state: "RESTORED_BY_MOTION",
      stillnessElapsedMinutes: 0,
      stillnessThresholdMinutes: stillnessMin,
      volumeMultiplier: 1.0,
      isAudioSuspended: false,
      westernDigits: true,
      timestamp: now
    };
  }

  const idleTimeMs = Math.max(0, now - lastMove);
  const idleMinutes = Math.floor(idleTimeMs / 60000);

  let state = "STILLNESS_COUNTDOWN";
  let volMult = 1.0;
  let isSuspended = false;
  let fadeProgress = 0;

  if (idleTimeMs >= (stillnessMs + fadeMs)) {
    state = "SLEEP_SUSPENDED";
    volMult = 0.0;
    isSuspended = true;
    fadeProgress = 100;
  } else if (idleTimeMs >= stillnessMs) {
    state = "FADING_DOWN";
    const fadeElapsedMs = idleTimeMs - stillnessMs;
    fadeProgress = Math.min(100, Math.round((fadeElapsedMs / fadeMs) * 100));
    volMult = Math.max(0.0, Math.round((1.0 - (fadeElapsedMs / fadeMs)) * 100) / 100);
  }

  return {
    versionCode: 168,
    versionName: "4.7.8",
    sleepTimerActive: true,
    state: state,
    stillnessElapsedMinutes: idleMinutes,
    stillnessThresholdMinutes: stillnessMin,
    fadeDurationMinutes: fadeMin,
    fadeProgressPercent: fadeProgress,
    volumeMultiplier: volMult,
    isAudioSuspended: isSuspended,
    westernDigits: true,
    timestamp: now
  };
}

if (typeof window !== "undefined") {
  window.dfGetMotionSleepFadeMetrics = dfGetMotionSleepFadeMetrics;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfGetMotionSleepFadeMetrics = dfGetMotionSleepFadeMetrics;
}

// ============================================================================
// MISSION #349: High Refresh Rate 60/120 FPS Jitter-Free Compositor Lock (v4.7.9)
// ============================================================================
function dfLockJitterFreeCompositor(options, frameDeltasSample) {
  const opts = options || {};
  const samples = Array.isArray(frameDeltasSample) && frameDeltasSample.length >= 3
    ? frameDeltasSample
    : [8.3, 8.4, 8.3, 8.5, 8.3, 8.4, 8.3];

  let sum = 0;
  for (const d of samples) {
    sum += (typeof d === "number" && d > 0 ? d : 16.67);
  }
  const avgDelta = Math.round((sum / samples.length) * 100) / 100;

  let targetFps = 60;
  let targetDelta = 16.67;

  if (avgDelta <= 9.5) {
    targetFps = 120;
    targetDelta = 8.33;
  } else if (avgDelta <= 13.0) {
    targetFps = 90;
    targetDelta = 11.11;
  } else {
    targetFps = 60;
    targetDelta = 16.67;
  }

  let varianceSum = 0;
  let droppedFrames = 0;
  const dropThreshold = targetDelta * 1.5;

  for (const d of samples) {
    const diff = d - avgDelta;
    varianceSum += (diff * diff);
    if (d > dropThreshold) {
      droppedFrames++;
    }
  }

  const jitterVariance = Math.round(Math.sqrt(varianceSum / samples.length) * 100) / 100;
  const isJitterFree = jitterVariance <= 2.5 && droppedFrames === 0;

  let health = "EXCELLENT_" + targetFps + "FPS";
  if (droppedFrames > 0 || jitterVariance > 3.0) {
    health = "MICRO_STUTTERS_DETECTED";
  }

  return {
    versionCode: 169,
    versionName: "4.7.9",
    compositorLocked: true,
    targetFps: targetFps,
    targetFrameDeltaMs: targetDelta,
    averageFrameDeltaMs: avgDelta,
    jitterVarianceMs: jitterVariance,
    isJitterFree: isJitterFree,
    droppedFramesCount: droppedFrames,
    compositorHealth: health,
    recommendedEasing: "cubic-bezier(0.16, 1, 0.3, 1)",
    westernDigits: true,
    timestamp: Date.now()
  };
}

if (typeof window !== "undefined") {
  window.dfLockJitterFreeCompositor = dfLockJitterFreeCompositor;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfLockJitterFreeCompositor = dfLockJitterFreeCompositor;
}

