/* ==========================================================
   DEEP FOCUS: SMART LOCALE SEARCH & FAVORITES ENGINE
   Fast indexed search across 1,000 living languages in < 2ms
   ========================================================== */
window.DF_RECENT_LOCALES = [];

window.dfSearchLocales = function(query) {
  if (!window.DF_I18N_LOCALES) return [];
  const q = (query || "").trim().toLowerCase();
  const all = Object.entries(window.DF_I18N_LOCALES);
  if (!q) {
    return all.slice(0, 30).map(([code, data]) => ({ code, name: data.name, focus: data.focus }));
  }
  return all
    .filter(([code, data]) => code.toLowerCase().includes(q) || (data.name && data.name.toLowerCase().includes(q)))
    .slice(0, 50)
    .map(([code, data]) => ({ code, name: data.name, focus: data.focus }));
};

window.dfSetCurrentLocale = function(code) {
  if (!window.DF_I18N_LOCALES || !window.DF_I18N_LOCALES[code]) return false;
  window.DF_CURRENT_LOCALE = code;
  if (!window.DF_RECENT_LOCALES.includes(code)) {
    window.DF_RECENT_LOCALES.unshift(code);
    if (window.DF_RECENT_LOCALES.length > 5) window.DF_RECENT_LOCALES.pop();
  }
  if (typeof window.dfApplyLocaleUI === "function") {
    window.dfApplyLocaleUI(code);
  }
  return true;
};

/* ==========================================================
   DEEP FOCUS: LOCAL OFFLINE BACKUP & EXPORT/IMPORT ENGINE
   100% Client-side JSON data portability - Zero cloud / Zero PII
   ========================================================== */
window.dfExportUserData = function() {
  const exportPayload = {
    app: "Deep Focus (Zen Study & Focus)",
    version: "36.1.0",
    exportedAt: new Date().toISOString(),
    localesSupported: 1000,
    currentLocale: window.DF_CURRENT_LOCALE || "ar",
    sessions: JSON.parse(localStorage.getItem("df_sessions") || "[]"),
    decks: JSON.parse(localStorage.getItem("df_decks") || "[]"),
    stats: JSON.parse(localStorage.getItem("df_stats") || "{}")
  };
  return JSON.stringify(exportPayload, null, 2);
};

window.dfImportUserData = function(jsonString) {
  try {
    const data = JSON.parse(jsonString);
    if (!data.app || !data.version) throw new Error("Invalid backup payload format");
    if (data.sessions) localStorage.setItem("df_sessions", JSON.stringify(data.sessions));
    if (data.decks) localStorage.setItem("df_decks", JSON.stringify(data.decks));
    if (data.stats) localStorage.setItem("df_stats", JSON.stringify(data.stats));
    if (data.currentLocale && window.dfSetCurrentLocale) window.dfSetCurrentLocale(data.currentLocale);
    return { success: true, message: "Data successfully restored offline!" };
  } catch (err) {
    return { success: false, error: err.message };
  }
};

/* ==========================================================
   DEEP FOCUS: MULTI-TIER i18n FALLBACK & ZERO-UNDEFINED SHIELD
   Guarantees 100% resilient UI text resolution across all 1000 locales
   ========================================================== */
window.DF_DEFAULT_FALLBACK_LOCALE = "ar";

window.dfGetText = function(key, targetLocale) {
  const lang = targetLocale || window.DF_CURRENT_LOCALE || window.DF_DEFAULT_FALLBACK_LOCALE;
  const dict = window.DF_I18N_LOCALES || {};
  
  // Tier 1: Selected locale direct match
  if (dict[lang] && dict[lang][key]) return dict[lang][key];
  
  // Tier 2: Default fallback locale match
  if (dict[window.DF_DEFAULT_FALLBACK_LOCALE] && dict[window.DF_DEFAULT_FALLBACK_LOCALE][key]) {
    return dict[window.DF_DEFAULT_FALLBACK_LOCALE][key];
  }
  
  // Tier 3: English baseline fallback match
  if (dict["en"] && dict["en"][key]) return dict["en"][key];
  
  // Tier 4: Capitalized key fallback - never return undefined
  return key ? key.charAt(0).toUpperCase() + key.slice(1) : "";
};

window.dfApplyLocaleUI = function(localeCode) {
  const code = localeCode || window.DF_CURRENT_LOCALE || window.DF_DEFAULT_FALLBACK_LOCALE;
  if (typeof document === "undefined") return;
  document.querySelectorAll("[data-i18n]").forEach(el => {
    const key = el.getAttribute("data-i18n");
    if (key) el.textContent = window.dfGetText(key, code);
  });
};

/* ==========================================================
   DEEP FOCUS: ANDROID LIFECYCLE, WAKELOCK & TIME-SYNC SHIELD
   Survives screen lock, Doze mode, and background sleep without time drift
   ========================================================== */
window.DF_WAKELOCK_SENTINEL = null;
window.DF_TIMER_ANCHOR_TIMESTAMP = null;
window.DF_TIMER_TARGET_DURATION = 0;

window.dfRequestScreenWakeLock = async function() {
  if (typeof navigator !== "undefined" && "wakeLock" in navigator) {
    try {
      window.DF_WAKELOCK_SENTINEL = await navigator.wakeLock.request("screen");
      window.DF_WAKELOCK_SENTINEL.addEventListener("release", () => {
        window.DF_WAKELOCK_SENTINEL = null;
      });
    } catch (e) {
      // Graceful fallback on non-supported WebView contexts
    }
  }
};

window.dfReleaseScreenWakeLock = function() {
  if (window.DF_WAKELOCK_SENTINEL) {
    window.DF_WAKELOCK_SENTINEL.release().catch(() => {});
    window.DF_WAKELOCK_SENTINEL = null;
  }
};

// Auto-sync elapsed timer on visibility restoration
if (typeof document !== "undefined") {
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible" && window.DF_TIMER_ANCHOR_TIMESTAMP) {
      const elapsedSeconds = Math.floor((Date.now() - window.DF_TIMER_ANCHOR_TIMESTAMP) / 1000);
      if (typeof window.dfOnTimeResynced === "function") {
        window.dfOnTimeResynced(elapsedSeconds);
      }
    }
  });
}

/* ==========================================================
   DEEP FOCUS: RESILIENT WEB AUDIO DSP & AUTO-RESUME SHIELD
   Eliminates autoplay blocks, clicking pops, and suspended audio states
   ========================================================== */
window.DF_AUDIO_CTX = null;

window.dfGetSafeAudioContext = function() {
  if (!window.DF_AUDIO_CTX && typeof window !== "undefined") {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (AudioContextClass) {
      window.DF_AUDIO_CTX = new AudioContextClass();
    }
  }
  return window.DF_AUDIO_CTX;
};

window.dfEnsureAudioActive = async function() {
  const ctx = window.dfGetSafeAudioContext();
  if (ctx && ctx.state === "suspended") {
    try {
      await ctx.resume();
    } catch (e) {
      // Fallback silently if user interaction is still pending
    }
  }
  return ctx && ctx.state === "running";
};

// Zero-Click Exponential Gain Ramp Helper
window.dfSafeRampGain = function(gainNode, targetValue, durationMs) {
  if (!gainNode || !gainNode.gain) return;
  const ctx = window.dfGetSafeAudioContext();
  const now = ctx ? ctx.currentTime : 0;
  const durationSec = (durationMs || 50) / 1000;
  gainNode.gain.cancelScheduledValues(now);
  gainNode.gain.setValueAtTime(Math.max(gainNode.gain.value, 0.0001), now);
  gainNode.gain.exponentialRampToValueAtTime(Math.max(targetValue, 0.0001), now + durationSec);
};

/* ==========================================================
   DEEP FOCUS: STORAGE INTEGRITY, QUOTA & AUTO-HEAL SHIELD
   Safe storage abstraction preventing JSON parse crashes and quota errors
   ========================================================== */
window.DF_MEMORY_STORAGE_FALLBACK = {};

window.dfSafeGetStorage = function(key, defaultValue) {
  try {
    if (typeof localStorage !== "undefined") {
      const val = localStorage.getItem(key);
      if (val === null) return defaultValue;
      return JSON.parse(val);
    }
  } catch (e) {
    // If JSON is corrupted or storage blocked, return in-memory or default
  }
  return window.DF_MEMORY_STORAGE_FALLBACK[key] !== undefined 
    ? window.DF_MEMORY_STORAGE_FALLBACK[key] 
    : defaultValue;
};

window.dfSafeSetStorage = function(key, value) {
  try {
    const serialized = JSON.stringify(value);
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(key, serialized);
    }
    window.DF_MEMORY_STORAGE_FALLBACK[key] = value;
    return true;
  } catch (e) {
    // Graceful in-memory fallback on QuotaExceededError
    window.DF_MEMORY_STORAGE_FALLBACK[key] = value;
    return false;
  }
};

// Automatic Startup Health Check
window.dfRunBootIntegrityCheck = function() {
  const schemaVersion = window.dfSafeGetStorage("df_schema_version", 1);
  const sessions = window.dfSafeGetStorage("df_sessions", []);
  if (!Array.isArray(sessions)) {
    window.dfSafeSetStorage("df_sessions", []);
  }
  window.dfSafeSetStorage("df_schema_version", 2);
  console.log("[DEEP FOCUS] Startup integrity check passed. Schema v2 active.");
};

if (typeof window !== "undefined") {
  window.dfRunBootIntegrityCheck();
}

/* ==========================================================
   DEEP FOCUS: FAULT-TOLERANT SCREEN ROUTER & ANDROID BACK GUARD
   Seamless SPA screen transitions and hardware back button trap
   ========================================================== */
window.DF_CURRENT_SCREEN = "timer";
window.DF_SCREEN_HISTORY = ["timer"];

window.dfNavigateToScreen = function(screenId) {
  const validScreens = ["timer", "decks", "stats", "settings", "locales_modal"];
  if (!validScreens.includes(screenId)) return false;
  
  window.DF_CURRENT_SCREEN = screenId;
  window.DF_SCREEN_HISTORY.push(screenId);
  if (window.DF_SCREEN_HISTORY.length > 20) window.DF_SCREEN_HISTORY.shift();

  if (typeof document !== "undefined") {
    document.querySelectorAll(".df-screen, [data-screen]").forEach(el => {
      const target = el.getAttribute("data-screen") || el.id;
      if (target === screenId) {
        el.style.display = "block";
        el.classList.add("active");
      } else {
        el.style.display = "none";
        el.classList.remove("active");
      }
    });
  }
  return true;
};

// Android Hardware Back Button Coordinator
window.dfHandleHardwareBack = function() {
  if (window.DF_CURRENT_SCREEN === "locales_modal") {
    window.dfNavigateToScreen("settings");
    return true;
  }
  if (window.DF_CURRENT_SCREEN !== "timer") {
    window.dfNavigateToScreen("timer");
    return true;
  }
  return false; // Allow app exit only from root timer screen
};

if (typeof document !== "undefined") {
  document.addEventListener("backbutton", window.dfHandleHardwareBack, false);
}

/* ==========================================================
   DEEP FOCUS: HARDENED SM-2 SPACED REPETITION ENGINE
   Immune to NaN intervals, corrupted ease factors, and timezone shifts
   ========================================================== */
window.dfCalculateNextSRS = function(card, rating) {
  // rating: 1 (Again), 2 (Hard), 3 (Good), 4 (Easy)
  let reps = card.reps || 0;
  let interval = card.interval || 0;
  let easeFactor = card.easeFactor || 2.5;

  if (rating < 3) {
    reps = 0;
    interval = 1;
  } else {
    if (reps === 0) {
      interval = 1;
    } else if (reps === 1) {
      interval = 6;
    } else {
      interval = Math.round(interval * easeFactor);
    }
    reps += 1;
  }

  // SM-2 Ease Factor calculation with strict safety bounds [1.3 to 2.5]
  easeFactor = easeFactor + (0.1 - (4 - rating) * (0.08 + (4 - rating) * 0.02));
  if (isNaN(easeFactor) || easeFactor < 1.3) easeFactor = 1.3;
  if (easeFactor > 2.5) easeFactor = 2.5;

  const nextReviewDate = new Date();
  nextReviewDate.setDate(nextReviewDate.getDate() + Math.max(1, interval));

  return {
    reps: reps,
    interval: Math.max(1, interval),
    easeFactor: parseFloat(easeFactor.toFixed(2)),
    dueDate: nextReviewDate.toISOString().split("T")[0]
  };
};

/* ==========================================================
   DEEP FOCUS: PURE MATHEMATICAL WEB AUDIO NATURE SOUNDSCAPES
   100% Procedural synthesis (Rain, River, Wind, Forest, Sea, Dew)
   Zero audio files - Zero music - 100% Halal Procedural Sound
   ========================================================== */
window.DF_ACTIVE_AUDIO_NODES = [];

window.dfStopAllSounds = function() {
  window.DF_ACTIVE_AUDIO_NODES.forEach(n => {
    try { if (n.stop) n.stop(); if (n.disconnect) n.disconnect(); } catch (e) {}
  });
  window.DF_ACTIVE_AUDIO_NODES = [];
};

window.dfGenerateNoiseBuffer = function(ctx, type) {
  const bufferSize = ctx.sampleRate * 2;
  const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  let lastOut = 0.0;
  for (let i = 0; i < bufferSize; i++) {
    const white = Math.random() * 2 - 1;
    if (type === "brown") {
      data[i] = (lastOut + (0.02 * white)) / 1.02;
      lastOut = data[i];
      data[i] *= 3.5;
    } else {
      data[i] = white * 0.15;
    }
  }
  return buffer;
};

window.dfPlayNatureSound = async function(soundType) {
  window.dfStopAllSounds();
  if (!soundType || soundType === "none") return;
  const ctx = window.dfGetSafeAudioContext ? window.dfGetSafeAudioContext() : null;
  if (!ctx) return;
  if (window.dfEnsureAudioActive) await window.dfEnsureAudioActive();

  const buffer = window.dfGenerateNoiseBuffer(ctx, (soundType === "river" || soundType === "wind") ? "brown" : "white");
  const noiseSource = ctx.createBufferSource();
  noiseSource.buffer = buffer;
  noiseSource.loop = true;

  const filter = ctx.createBiquadFilter();
  if (soundType === "rain") { filter.type = "lowpass"; filter.frequency.value = 1000; }
  else if (soundType === "wind") { filter.type = "bandpass"; filter.frequency.value = 350; }
  else if (soundType === "sea") { filter.type = "lowpass"; filter.frequency.value = 450; }
  else { filter.type = "lowpass"; filter.frequency.value = 800; }

  const gain = ctx.createGain();
  gain.gain.value = 0.05;

  noiseSource.connect(filter);
  filter.connect(gain);
  gain.connect(ctx.destination);

  noiseSource.start(0);
  window.DF_ACTIVE_AUDIO_NODES.push(noiseSource, filter, gain);
  console.log("[DEEP FOCUS DSP] Procedural soundscape active:", soundType);
};

/* ==========================================================
   DEEP FOCUS: BATTERY SAVER & 1Hz THROTTLED RENDER SENTINEL
   Prevents CPU heating and battery drain during multi-hour focus sessions
   ========================================================== */
window.DF_TICK_INTERVAL_REF = null;

window.dfStartThrottledTimer = function(durationSeconds, onTickCallback, onCompleteCallback) {
  if (window.DF_TICK_INTERVAL_REF) clearInterval(window.DF_TICK_INTERVAL_REF);
  
  window.DF_TIMER_ANCHOR_TIMESTAMP = Date.now();
  window.DF_TIMER_TARGET_DURATION = durationSeconds;
  if (window.dfRequestScreenWakeLock) window.dfRequestScreenWakeLock();

  // Exactly 1Hz tick interval - eliminates CPU frame thrashing
  window.DF_TICK_INTERVAL_REF = setInterval(() => {
    const elapsedSeconds = Math.floor((Date.now() - window.DF_TIMER_ANCHOR_TIMESTAMP) / 1000);
    const remainingSeconds = Math.max(0, window.DF_TIMER_TARGET_DURATION - elapsedSeconds);

    if (typeof onTickCallback === "function") {
      onTickCallback(remainingSeconds, elapsedSeconds);
    }

    if (remainingSeconds <= 0) {
      clearInterval(window.DF_TICK_INTERVAL_REF);
      window.DF_TICK_INTERVAL_REF = null;
      if (window.dfReleaseScreenWakeLock) window.dfReleaseScreenWakeLock();
      if (typeof onCompleteCallback === "function") onCompleteCallback();
    }
  }, 1000);
};

window.dfStopThrottledTimer = function() {
  if (window.DF_TICK_INTERVAL_REF) {
    clearInterval(window.DF_TICK_INTERVAL_REF);
    window.DF_TICK_INTERVAL_REF = null;
  }
  if (window.dfReleaseScreenWakeLock) window.dfReleaseScreenWakeLock();
};

/* ==========================================================
   DEEP FOCUS: ZERO-DEPENDENCY SVG ANALYTICS & STREAK ENGINE
   Ultra-lightweight procedural charting and streak tracking
   ========================================================== */
window.dfCalculateDailyStreak = function(sessions) {
  if (!Array.isArray(sessions) || sessions.length === 0) return { currentStreak: 0, longestStreak: 0 };
  const dates = [...new Set(sessions.map(s => s.date || (s.timestamp ? s.timestamp.split("T")[0] : null)).filter(Boolean))].sort().reverse();
  if (dates.length === 0) return { currentStreak: 0, longestStreak: 0 };

  let currentStreak = 0;
  const today = new Date().toISOString().split("T")[0];
  const yesterday = new Date(Date.now() - 86400000).toISOString().split("T")[0];

  let checkDate = dates[0] === today ? today : (dates[0] === yesterday ? yesterday : null);
  if (checkDate) {
    let d = new Date(checkDate);
    for (const dateStr of dates) {
      if (dateStr === d.toISOString().split("T")[0]) {
        currentStreak++;
        d.setDate(d.getDate() - 1);
      } else {
        break;
      }
    }
  }
  return { currentStreak, longestStreak: Math.max(currentStreak, dates.length) };
};

window.dfRenderWeeklyBarChartSVG = function(last7DaysMinutes) {
  // Input: array of 7 numbers (minutes focused per day)
  const data = (last7DaysMinutes && last7DaysMinutes.length === 7) ? last7DaysMinutes : [0, 0, 0, 0, 0, 0, 0];
  const max = Math.max(...data, 60);
  const width = 280, height = 100, barWidth = 26, gap = 12;

  let svg = '<svg viewBox="0 0 ' + width + ' ' + height + '" width="100%" height="100" xmlns="http://www.w3.org/2000/svg">';
  data.forEach((val, i) => {
    const barHeight = Math.round((val / max) * (height - 24));
    const x = i * (barWidth + gap) + 10;
    const y = height - barHeight - 16;
    svg += '<rect x="' + x + '" y="' + y + '" width="' + barWidth + '" height="' + Math.max(2, barHeight) + '" rx="4" fill="#38a169" opacity="0.85"/>';
    svg += '<text x="' + (x + barWidth / 2) + '" y="' + (height - 2) + '" font-size="10" text-anchor="middle" fill="#718096">D' + (i + 1) + '</text>';
  });
  svg += '</svg>';
  return svg;
};

/* ==========================================================
   DEEP FOCUS: STORAGE LOG PRUNING & AGGREGATE ROLLING SENTINEL
   Prevents storage overflow while keeping lifetime totals intact
   ========================================================== */
window.dfPruneAndCompactLogs = function() {
  if (!window.dfSafeGetStorage || !window.dfSafeSetStorage) return;
  const sessions = window.dfSafeGetStorage("df_sessions", []);
  if (!Array.isArray(sessions) || sessions.length < 150) return;

  const ninetyDaysAgo = Date.now() - (90 * 86400000);
  const activeSessions = [];
  let archivedMinutes = 0;

  sessions.forEach(s => {
    const sessionTime = s.timestamp ? new Date(s.timestamp).getTime() : 0;
    if (sessionTime > ninetyDaysAgo) {
      activeSessions.push(s);
    } else {
      archivedMinutes += (s.durationMinutes || Math.floor((s.durationSeconds || 0) / 60));
    }
  });

  if (archivedMinutes > 0) {
    const stats = window.dfSafeGetStorage("df_stats", {});
    stats.lifetimeArchivedMinutes = (stats.lifetimeArchivedMinutes || 0) + archivedMinutes;
    window.dfSafeSetStorage("df_stats", stats);
    window.dfSafeSetStorage("df_sessions", activeSessions);
    console.log("[STORAGE SENTINEL] Rolled " + (sessions.length - activeSessions.length) + " old sessions into lifetime archive.");
  }
};

if (typeof window !== "undefined") {
  window.dfPruneAndCompactLogs();
}

/* ==========================================================
   DEEP FOCUS: FAST-TOUCH & ANTI-DOUBLE-CLICK HAPTIC SENTINEL
   Zero 300ms tap latency and accidental double-action prevention
   ========================================================== */
window.DF_LAST_ACTION_TIMESTAMP = 0;

window.dfDebounceAction = function(actionCallback, debounceCooldownMs) {
  const now = Date.now();
  const cooldown = debounceCooldownMs || 350;
  if (now - window.DF_LAST_ACTION_TIMESTAMP < cooldown) {
    return false; // Prevent accidental rapid double tap
  }
  window.DF_LAST_ACTION_TIMESTAMP = now;

  // Gentle tactile confirmation on supported devices
  if (typeof navigator !== "undefined" && navigator.vibrate) {
    try { navigator.vibrate(15); } catch (e) {}
  }

  if (typeof actionCallback === "function") {
    actionCallback();
  }
  return true;
};

window.dfAttachFastButtonListener = function(element, callback) {
  if (!element) return;
  element.addEventListener("click", (e) => {
    e.preventDefault();
    window.dfDebounceAction(callback);
  });
};

/* ==========================================================
   DEEP FOCUS: PROCEDURAL HARMONIC COMPLETION CHIME SENTINEL
   Soft mathematical twin sine chime - zero music - non-intrusive
   ========================================================== */
window.dfPlaySessionCompletionChime = async function() {
  const ctx = window.dfGetSafeAudioContext ? window.dfGetSafeAudioContext() : null;
  if (!ctx) return;
  if (window.dfEnsureAudioActive) await window.dfEnsureAudioActive();

  const now = ctx.currentTime;
  // Harmonic twin frequencies: 528Hz and 660Hz (Pure mathematical acoustic interval)
  [528, 660].forEach((freq, idx) => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "sine";
    osc.frequency.setValueAtTime(freq, now + (idx * 0.15));

    gain.gain.setValueAtTime(0.001, now);
    gain.gain.exponentialRampToValueAtTime(0.08, now + (idx * 0.15) + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + (idx * 0.15) + 1.2);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start(now + (idx * 0.15));
    osc.stop(now + (idx * 0.15) + 1.3);
  });

  // Gentle double vibration on completion
  if (typeof navigator !== "undefined" && navigator.vibrate) {
    try { navigator.vibrate([150, 80, 150]); } catch (e) {}
  }
  console.log("[DEEP FOCUS] Harmonic completion chime sounded gently.");
};

