    continuousHoursFocused: parseFloat(continuousHours.toFixed(1)),
    averageCardLatencySeconds: parseFloat(avgLatency.toFixed(1)),
    fatigueLevel: continuousHours > 3 ? "HIGH" : (continuousHours > 1.5 ? "MODERATE" : "FRESH")
