/* ==========================================================
   DEEP FOCUS: UNICODE QUOTATION & GLYPH PAIRING AUDITOR (v55.2.0)
   Validates balanced quotation brackets (« », 「 」, “ ”) across 1,000 locales
   ========================================================== */
window.dfValidateQuotationBalance = function(text) {
  if (!text || typeof text !== "string") return true;
  const pairs = [["«", "»"], ["「", "」"], ["“", "”"], ["(", ")"]];
  let isBalanced = true;

  pairs.forEach(([open, close]) => {
    const openCount = (text.split(open).length - 1);
    const closeCount = (text.split(close).length - 1);
    if (openCount !== closeCount) isBalanced = false;
  });

  return isBalanced;
};

/* ==========================================================
   DEEP FOCUS: CONTINUOUS SCRIPT ZERO-WIDTH WRAPPER (KHMER/THAI)
   Injects boundary break hints (\u200B) preventing mid-syllable word severance
   ========================================================== */
window.DF_SPACELESS_SCRIPTS_LOCALES = ["khm", "tha", "lao", "mya"];

window.dfSegmentContinuousScript = function(text, localeCode) {
  if (!text || typeof text !== "string") return "";
  const code = localeCode || window.DF_CURRENT_LOCALE || "";
  if (!window.DF_SPACELESS_SCRIPTS_LOCALES.includes(code)) return text;
  
  // Safe zero-width space injection allowing natural browser line breaks
  return text.replace(/([\u1780-\u17FF\u0E00-\u0E7F])/g, "$1\u200B");
};

/* ==========================================================
   DEEP FOCUS: CAUCASIAN CYRILLIC PALOCHKA GLYPH NORMALIZER
   Harmonizes Caucasian aspiration character (\u04C0) preventing Latin font clashes
   ========================================================== */
window.dfNormalizeCaucasianPalochka = function(text) {
  if (!text || typeof text !== "string") return "";
  // Unify ASCII pipe/Latin-I masquerading as Caucasian Palochka to authentic Cyrillic \u04C0
  return text.replace(/([\u0400-\u04FF])[|I1]([\u0400-\u04FF])/g, "$1\u04C0$2");
};

/* ==========================================================
   DEEP FOCUS: UNIVERSAL TYPOGRAPHIC PARITY AUDITOR (v55.3.0)
   Validates zero tofu glyphs, zero clipped diacritics and bidi isolation
   ========================================================== */
